import { parseBoardCode } from '../deck.ts';
import { isWon } from '../game.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { freshBoardCode } from '../session/fresh-board.ts';
import type { GameState } from '../game.ts';

export interface Result { moves: number; elapsedMs: number }
export interface Match { players: [number, number]; code: string; results: [Result | null, Result | null]; winner: number | null }
export type Phase = 'ready' | 'playing' | 'turnDone' | 'matchDone' | 'champion';
export interface Tournament { names: string[]; rounds: Match[][]; round: number; match: number; phase: Phase; game: string | null }
export const normalizeName = (name: string) => name.trim().replace(/\s+/gu, ' ').normalize('NFC');
export function nameError(names: string[]): string {
  if (names.some((name) => [...name].length < 2 || [...name].length > 20)) return 'Use 2 to 20 characters.';
  if (new Set(names.map((name) => name.toLowerCase())).size !== names.length) return 'Each name must be different.';
  return '';
}
export function roundName(count: number): string { return count === 4 ? 'Quarterfinal' : count === 2 ? 'Semifinal' : 'Final'; }
function sizeFor(count: number): number { return count === 4 ? 4 : count === 2 ? 6 : 8; }
function deal(size: number, used: string[]): string { let code: string; do { code = freshBoardCode(size); } while (used.includes(code)); return code; }
function makeRound(pairs: [number, number][], used: string[]): Match[] {
  return pairs.map((players) => { const code = deal(sizeFor(pairs.length), used); used.push(code); return { players, code, results: [null, null], winner: null }; });
}
export function createTournament(names: string[]): Tournament {
  const pairs: [number, number][] = names.length === 4 ? [[0, 3], [1, 2]] : [[0, 7], [3, 4], [2, 5], [1, 6]];
