}
export function currentMatch(t: Tournament): Match { return t.rounds[t.round]![t.match]!; }
export function currentPlayer(t: Tournament): number { const m = currentMatch(t); return m.players[m.results[0] ? 1 : 0]!; }
export function recordResult(t: Tournament, game: GameState): Tournament {
  const rounds = t.rounds.map((round) => round.map((m) => ({ ...m, players: [...m.players] as [number, number], results: [...m.results] as [Result | null, Result | null] })));
  const match = rounds[t.round]![t.match]!;
  const result = { moves: game.moves, elapsedMs: game.elapsedMs };
  if (!match.results[0]) { match.results[0] = result; return { ...t, rounds, phase: 'turnDone', game: null }; }
  match.results[1] = result;
  const first = match.results[0];
  match.winner = first.moves !== result.moves ? match.players[first.moves < result.moves ? 0 : 1] : first.elapsedMs !== result.elapsedMs ? match.players[first.elapsedMs < result.elapsedMs ? 0 : 1] : Math.min(...match.players);
